create type public.medical_report_type as enum ('LAB_RESULT','IMAGING','DISCHARGE_SUMMARY','OTHER');
create table public.medical_reports (id uuid primary key default gen_random_uuid(), test_order_id uuid not null references public.test_orders(id) on delete restrict, patient_id uuid not null references public.patients(id) on delete restrict, facility_id uuid not null references public.healthcare_facilities(id) on delete restrict, uploaded_by uuid not null references public.users(id) on delete restrict, report_title text not null, report_type public.medical_report_type not null default 'LAB_RESULT', storage_path text not null unique, original_filename text not null, mime_type text not null, file_size bigint not null check (file_size > 0 and file_size <= 10485760), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint medical_reports_title_nonempty check (length(trim(report_title)) > 0), constraint medical_reports_filename_nonempty check (length(trim(original_filename)) > 0), constraint medical_reports_mime_check check (mime_type in ('application/pdf','image/png','image/jpeg','image/webp')));
create index medical_reports_patient_created_idx on public.medical_reports (patient_id, created_at desc); create index medical_reports_order_idx on public.medical_reports (test_order_id, created_at desc); create index medical_reports_facility_created_idx on public.medical_reports (facility_id, created_at desc);
alter table public.medical_reports enable row level security;
create or replace function public.set_medical_report_updated_at() returns trigger language plpgsql security invoker set search_path = public as $$ begin new.updated_at = now(); return new; end; $$;
drop trigger if exists medical_reports_set_updated_at on public.medical_reports; create trigger medical_reports_set_updated_at before update on public.medical_reports for each row execute function public.set_medical_report_updated_at();
create or replace function public.validate_medical_report_relationship() returns trigger language plpgsql security invoker set search_path = public as $$ declare v_patient_id uuid; v_facility_id uuid; begin select patient_id, facility_id into v_patient_id, v_facility_id from public.test_orders where id = new.test_order_id; if v_patient_id is null or v_facility_id is null then raise exception using errcode = '22023', message = 'Test order not found'; end if; if new.patient_id <> v_patient_id or new.facility_id <> v_facility_id then raise exception using errcode = '23514', message = 'Report must match the test order patient and facility'; end if; if tg_op = 'UPDATE' and (old.test_order_id <> new.test_order_id or old.patient_id <> new.patient_id or old.facility_id <> new.facility_id or old.storage_path <> new.storage_path or old.uploaded_by <> new.uploaded_by) then raise exception using errcode = '42501', message = 'Report relationships and storage path are immutable'; end if; return new; end; $$;
drop trigger if exists medical_reports_validate_relationship on public.medical_reports; create trigger medical_reports_validate_relationship before insert or update on public.medical_reports for each row execute function public.validate_medical_report_relationship();
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values ('medical-reports', 'medical-reports', false, 10485760, array['application/pdf','image/png','image/jpeg','image/webp']::text[]) on conflict (id) do update set name = excluded.name, public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
create policy medical_reports_select_patient on public.medical_reports for select to authenticated using (exists (select 1 from public.patients p where p.id = patient_id and p.user_id = auth.uid()));
create policy medical_reports_select_doctor on public.medical_reports for select to authenticated using (exists (select 1 from public.test_orders o join public.doctors d on d.id = o.doctor_id where o.id = test_order_id and d.user_id = auth.uid() and d.approval_status = 'APPROVED'));
create policy medical_reports_select_admin on public.medical_reports for select to authenticated using (public.is_admin());
create policy medical_reports_insert_admin on public.medical_reports for insert to authenticated with check (public.is_admin() and uploaded_by = auth.uid()); create policy medical_reports_update_admin on public.medical_reports for update to authenticated using (public.is_admin()) with check (public.is_admin()); create policy medical_reports_delete_admin on public.medical_reports for delete to authenticated using (public.is_admin());
create policy medical_reports_storage_select on storage.objects for select to authenticated using (bucket_id = 'medical-reports' and (public.is_admin() or exists (select 1 from public.medical_reports mr where mr.storage_path = name and (exists (select 1 from public.patients p where p.id = mr.patient_id and p.user_id = auth.uid()) or exists (select 1 from public.test_orders o join public.doctors d on d.id = o.doctor_id where o.id = mr.test_order_id and d.user_id = auth.uid() and d.approval_status = 'APPROVED')))));
create policy medical_reports_storage_insert_admin on storage.objects for insert to authenticated with check (bucket_id = 'medical-reports' and public.is_admin()); create policy medical_reports_storage_update_admin on storage.objects for update to authenticated using (bucket_id = 'medical-reports' and public.is_admin()) with check (bucket_id = 'medical-reports' and public.is_admin()); create policy medical_reports_storage_delete_admin on storage.objects for delete to authenticated using (bucket_id = 'medical-reports' and public.is_admin());
